const storyCollection=[{title:'The Unsaid Thing',tag:'A STORY ABOUT HONESTY',image:photos.couple,chapters:[{text:'A close friend has been distant. You have noticed it for a few weeks. Tonight, you finally have a quiet moment together.',choices:['Ask openly what has changed.','Give the moment more space.','Begin with something warm.']},{text:'Your friend tells you they have been overwhelmed, and they were not sure how to say it.',choices:['Thank them for being honest.','Ask what they need right now.','Offer a simple plan to reconnect.']},{text:'As the evening ends, you realize connection can hold uncertainty without needing to resolve it all at once.',choices:['Take one small step toward openness.','Make room for more patience.','Celebrate the trust you have built.']}]},{title:'A Different Beginning',tag:'A STORY ABOUT CHOICE',image:photos.nature,chapters:[{text:'You have the chance to start something new, but it might change the life you already know.',choices:['Gather the facts.','Listen to your sense of direction.','Talk with someone who knows you.']},{text:'The opportunity becomes clearer. It still holds uncertainty, but so does staying exactly where you are.',choices:['Make a considered plan.','Give yourself one quiet day.','Test the idea in a small way.']},{text:'You realize there may not be a perfect decision, only one you can make with care and learn from.',choices:['Choose with intention.','Choose with self-trust.','Choose with curiosity.']}]},{title:'The Space Between',tag:'A STORY ABOUT BOUNDARIES',image:photos.journal,chapters:[{text:'Someone you love asks more of you than you have to give this week.',choices:['Say clearly what you can offer.','Take a moment to check your limits.','Offer kindness in a smaller way.']},{text:'They seem disappointed at first, then ask what would work better for both of you.',choices:['Make a specific agreement.','Protect some time for yourself.','Find a new way to show care.']},{text:'You discover that being close does not always mean being available at every moment.',choices:['Practice saying what you mean.','Value your own rhythm.','Choose connection with room to breathe.']}]}];
const state={route:'home',config:{accounts:false,ai:false,products:{}},user:null,entitlements:[],ipip:[],journey:null,answers:[],idx:0,result:null,reportHistory:[],journal:[],invites:[],shareUrl:'',inviteCode:'',invite:null,story:0,chapter:0,choices:[],mirror:[],busy:false,toastTimer:null,signMode:'register',consent:false};
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
async function request(url,{method='GET',json}={}){const res=await fetch(url,{method,credentials:'same-origin',headers:json?{'content-type':'application/json'}:{},body:json?JSON.stringify(json):undefined});const d=await res.json().catch(()=>({}));if(!res.ok)throw Error(d.error||'Request failed');return d}
function getLocal(key,fallback){try{return JSON.parse(localStorage.getItem('mirra2:'+key))??fallback}catch{return fallback}}
function putLocal(key,value){try{localStorage.setItem('mirra2:'+key,JSON.stringify(value))}catch{}}
async function boot(){try{const [config,items,me]=await Promise.all([request('/api/config'),request('/ipip-items.json'),request('/api/me')]);state.config=config;state.ipip=items;state.user=me.user;state.entitlements=me.entitlements||[]}catch(e){console.warn('MIRRA initial state',e);state.config={accounts:false,ai:false,products:{}};try{state.ipip=await request('/ipip-items.json')}catch{state.ipip=[]}}
const code=new URL(location.href).searchParams.get('invite');if(code){state.inviteCode=code;state.route='invite';await fetchInvite()}else if(location.hash.includes('membership'))state.route='membership';render()}
function route(name){state.route=name;window.scrollTo({top:0,behavior:'instant'});const url=new URL(location.href);url.searchParams.delete('invite');history.replaceState({},'',url.pathname+(name!=='home'?'#'+name:''));render()}
function refreshNav(){document.querySelectorAll('.desktop-nav [data-route]').forEach(n=>n.classList.toggle('active',n.dataset.route===state.route));const account=$('#account-action');if(account)account.innerHTML=state.user?escapeText(state.user.name.split(' ')[0])+' <span>↗</span>':'My space <span>↗</span>'}
function render(){refreshNav();const views={home,discover,quiz,report,together,invite,invites,journal,account,mirror,stories,membership,science};app.innerHTML=(views[state.route]||home)();document.title=(state.route==='home'?'MIRRA | The psychology of being human':'MIRRA | '+state.route[0].toUpperCase()+state.route.slice(1));$('#mobile-nav').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false')}
const heroFaces=`<figure>${image(photos.hero,'Editorial portrait of a reflective adult')}<figcaption>01 / THE INNER SELF</figcaption></figure><figure>${image(photos.man,'Portrait of a smiling young adult')}<figcaption>02 / CONNECTION</figcaption></figure><figure>${image(photos.older,'Portrait of an older adult')}<figcaption>03 / GROWTH</figcaption></figure>`;
function home(){return `<section class="hero container"><div class="hero-grid"><div class="hero-copy"><span class="eyebrow">MIRRA / THE PSYCHOLOGY OF BEING HUMAN</span><h1>The art of understanding <em>yourself.</em></h1><p class="lead">A quieter, more thoughtful way to explore the patterns that shape who you are, how you connect, and what you might become.</p><div class="group-buttons">${button('Begin your journey','discover')}${button('Explore relationships','together','')}</div><div class="hero-proof"><div><b>50</b><span>Public domain Big Five items</span></div><div><b>09</b><span>Original reflection chapters</span></div><div><b>01</b><span>Evolving personal space</span></div></div></div><div class="hero-art">${heroFaces}</div></div></section><div class="container marquee-strip"><span>PERSONALITY</span><i>✳</i><span>RELATIONSHIPS</span><i>✳</i><span>EMOTIONAL LIFE</span><i>✳</i><span>SELF REFLECTION</span><i>✳</i><span>GROWTH</span></div><section class="section container"><div class="section-head"><div><span class="eyebrow">CHOOSE YOUR OWN BEGINNING</span><h2 class="section-title">A world worth<br><em>exploring.</em></h2></div><p>There is no single way to understand a person. Each journey offers a different window into the everyday choices that make us human.</p></div>${cards(['ipip50','relationships','emotions'])}<div style="margin-top:35px">${button('See all experiences','discover','')}</div></section><section class="container feature-split"><div class="feature-copy"><span class="eyebrow">01 / THE LIVING PORTRAIT</span><h2>More than<br><em>a label.</em></h2><p>See your personality as a collection of dimensions, not a fixed type. Your reports remain yours, and your understanding can change as life does.</p><div class="proof"><span>Published IPIP item set</span><span>Private saved reports</span></div>${button('Explore the method','science','')}</div><div class="feature-image">${image(photos.woman,'Thoughtful portrait in natural light')}</div></section><section class="container feature-split reverse"><div class="feature-image">${image(photos.couple,'Group of friends spending time together')}</div><div class="feature-copy"><span class="eyebrow">02 / MIRRA TOGETHER</span><h2>The space<br>between <em>us.</em></h2><p>Invite someone you care about into a shared reflection. Discover where your answers meet and where a meaningful conversation might begin.</p>${button('Discover Together','together')}</div></section><section class="quote-section"><div class="container"><span class="eyebrow" style="color:#e8c5a7">A SMALL REMINDER</span><blockquote>“You are not a result to be decoded. You are a person worth <em>getting to know.</em>”</blockquote><small>MIRRA / OUR POINT OF VIEW</small></div></section><section class="section container"><div class="section-head"><div><span class="eyebrow">A PRIVATE PRACTICE</span><h2 class="section-title">Make room<br>to <em>reflect.</em></h2></div><p>Some discoveries happen in a questionnaire. Others arrive slowly in a journal, a conversation, or a choice.</p></div><div class="portrait-wall"><figure>${image(photos.woman2,'Woman in natural light')}</figure><figure>${image(photos.man2,'Man with relaxed expression')}</figure><figure>${image(photos.older,'Mature woman portrait')}</figure><figure>${image(photos.woman,'Adult woman portrait')}</figure></div><div class="group-buttons top-space">${button('Open your journal','journal')}${button('Explore interactive stories','stories','')}</div></section>`}
function cardData(key){if(key==='ipip50')return {title:'The Personality Atlas',tag:'FOUNDATIONS / IPIP 50',lede:'A 50 item public domain Big Five questionnaire with published item keys.',image:photos.woman};return {...genres[key],tag:genres[key].tag}}
function cards(keys){return `<div class="journey-grid">${keys.map((key,i)=>{const x=cardData(key);return `<article class="journey-card" role="button" tabindex="0" data-open="${key}"><div class="photo">${image(x.image,x.title)}<span>${x.tag}</span></div><div class="journey-body"><h3>${x.title}</h3><p>${x.lede}</p><div class="journey-footer"><span>${key==='ipip50'?'50':'08'} QUESTIONS · ${key==='ipip50'?'10':'3'} MIN</span><b>↗</b></div></div></article>`}).join('')}</div>`}
function intro(label,title,description){return `<section class="page-intro"><div class="container"><span class="eyebrow">${label}</span><h1>${title}</h1><p class="lead">${description}</p></div></section>`}
function discover(){return `${intro('THE MIRRA LIBRARY','Every story begins<br>with <em>curiosity.</em>','Choose a considered path into personality, relationships, emotions, habits and more. There is no perfect response. Just your own.') }<section class="page-body container">${cards(['ipip50',...Object.keys(genres)])}<div class="page-card top-space"><span class="eyebrow">THE ORIGINAL COLLECTION</span><h2 style="font:39px var(--display);margin:10px 0">Nine more journeys, still here.</h2><p class="small-text">Visit the original MIRRA assessment library with 134 questions across nine exploratory experiences.</p><a href="/classic" class="btn small">Visit the original library <span>↗</span></a></div></section>`}
function startQuiz(key){state.journey=key;state.answers=[];state.idx=0;route('quiz')}
function quiz(){const together=state.journey==='together';const ipip=state.journey==='ipip50';const desc=together?{title:'MIRRA Together',lede:'Eight questions to discover where your preferences meet.',image:photos.couple}:cardData(state.journey||'ipip50');const items=together?togetherQuestions.map((text,i)=>({text,options:togetherOptions[i]})):ipip?state.ipip:genres[state.journey]?.questions||[];if(!items.length)return `<div class="container page-body">We could not load this experience. ${button('Explore another','discover')}</div>`;const row=items[state.idx],value=state.answers[state.idx];const options=ipip?['Very inaccurate','Moderately inaccurate','Neither accurate nor inaccurate','Moderately accurate','Very accurate']:row.options;return `<div class="assessment-layout"><section class="assessment-core"><div class="quiz-header"><span>${escapeText(desc.title).toUpperCase()}</span><span>${String(state.idx+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}</span></div><div class="progress"><i style="width:${(state.idx+1)/items.length*100}%"></i></div><div class="assessment-question"><div class="qno">Question ${String(state.idx+1).padStart(2,'0')}.</div><h1>${escapeText(row.text)}</h1><p>${ipip?'As you are in everyday life, not as you wish to be.':desc.lede}</p><div class="answers" role="group" aria-label="Choose your response">${options.map((text,i)=>`<button class="answer ${value===i+1?'selected':''}" data-answer="${i+1}" aria-pressed="${value===i+1}"><span>${i+1}</span><span>${escapeText(text)}</span></button>`).join('')}</div></div><div class="quiz-foot"><button class="btn-link" data-action="previous">← Previous</button><button class="btn dark" data-action="next" ${value?'':'disabled'}>${state.idx+1===items.length?'See my reflection':'Continue'} <span>↗</span></button></div><div class="privacy-note">Your responses are private. You can explore without signing up. Sign in to save reports securely.</div></section><aside class="assessment-image">${image(desc.image,desc.title)}<span class="image-note">A closer look at you.</span></aside></div>`}
function scoreClientIPIP(answers){const names={E:'Extraversion',A:'Agreeableness',C:'Conscientiousness',S:'Emotional Stability',I:'Intellect & Imagination'},values=Object.fromEntries(Object.keys(names).map(k=>[k,[]]));state.ipip.forEach((x,i)=>values[x.dimension].push(x.reverse?6-answers[i]:answers[i]));return {instrument:'IPIP Big Five 50-item markers',dimensions:Object.keys(names).map(id=>{const mean=values[id].reduce((a,b)=>a+b,0)/10;return {id,name:names[id],rawMean:Number(mean.toFixed(2)),index:Math.round((mean-1)*25)}}),method:'Scores are transformed within-scale indices, not population percentiles.',clinical:false}}
async function completeQuiz(){const key=state.journey;if(key==='together'){if(!state.user){toast('Create a free account to send an invitation.');state.pendingTogether=[...state.answers];state.signMode='register';route('account');return}try{const d=await request('/api/invites',{method:'POST',json:{answers:state.answers}});state.shareUrl=d.url;await loadInvites();route('invites')}catch(e){toast(e.message)}return}
const score=key==='ipip50'?scoreClientIPIP(state.answers):{...summaries[[0,1,2,3].map(i=>state.answers.filter(v=>v===i+1).length).indexOf(Math.max(...[1,2,3,4].map(v=>state.answers.filter(x=>x===v).length)))],exploratory:true};state.result={journey:key,score,answers:[...state.answers],createdAt:new Date().toISOString()};putLocal('recentReport',state.result);if(state.user){try{const d=await request('/api/reports',{method:'POST',json:{journey:key,answers:state.answers,length:state.answers.length,summary:{label:score.name,description:score.description}}});state.result.score=d.score;await loadReports()}catch(e){toast('Saved on this device. Cloud sync was unavailable.')}}route('report')}
function report(){const r=state.result||getLocal('recentReport',null);if(!r)return `${intro('YOUR PORTRAIT','A space for <em>you.</em>','Complete an experience to see your reflections here.')}${button('Begin now','discover')}`;const scientific=r.journey==='ipip50';const score=r.score;const top=scientific?[...score.dimensions].sort((a,b)=>b.index-a.index)[0]:null;return `<section class="container report-hero"><div><span class="eyebrow">YOUR PRIVATE MIRRA PORTRAIT</span><h1>${scientific?'A portrait of <em>you.</em>':'A little more <em>clarity.</em>'}</h1><p>${scientific?'Your answers offer a view across five personality dimensions. The scores describe your responses to these items, not your worth or a permanent identity.':escapeText(score.description)}</p><span class="eyebrow">${new Date(r.createdAt).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})}</span></div><aside class="report-summary"><span class="eyebrow">YOUR REFLECTION</span><b>${scientific?escapeText(top.name):escapeText(score.name||score.label)}</b><p>${scientific?'Your strongest reported dimension in this assessment. Every dimension matters.':'A style you selected most often across these scenarios.'}</p></aside></section><section class="container report-section"><div><span class="eyebrow">THE DETAILS</span><h2 style="font:56px var(--display)">${scientific?'Your five dimensions.':'A moment of perspective.'}</h2>${scientific?score.dimensions.map(x=>`<div class="report-dimension"><span>${escapeText(x.name)}</span><div class="bar"><span style="width:${x.index}%"></span></div><b>${x.index}</b></div>`).join(''):`<div class="page-card"><p>${escapeText(score.description)}</p><p>When does this approach serve you well? When might another approach be useful?</p></div>`}</div><aside class="report-side"><span class="eyebrow">A NOTE ON INTERPRETATION</span><h2>Curiosity is more useful than a label.</h2><p>${scientific?'This report uses the public-domain IPIP 50-item Big Five markers and published scoring keys. The 0 to 100 numbers are transformed scores within the questionnaire, not percentiles or diagnostic cutoffs.':'These original scenario questions are exploratory prompts, not standardized psychological measurements.'}</p><p>Your story is more complex than any single assessment. Return to it with generosity and an open mind.</p></aside></section><section class="container report-actions"><button class="btn dark" data-action="download-card">Save my portrait <span>↓</span></button><button class="btn" data-action="share-result">Copy a private summary <span>↗</span></button>${button('Explore more','discover','')}${button('Invite someone','together','')}</section>`}
function together(){return `${intro('MIRRA TOGETHER','The space<br>between <em>us.</em>','The most interesting discovery is sometimes what happens when two perspectives meet. Explore connection without turning people into compatibility scores.')}<section class="page-body container"><div class="together-banner"><div class="copy"><span class="eyebrow">THE SHARED REFLECTION</span><h2>Two people.<br>Two perspectives.<br>One conversation.</h2><p>Answer eight gentle prompts, then invite someone to do the same. Find shared preferences, differences, and questions worth talking about.</p><button class="btn cream" data-action="start-together">Create an invitation <span>↗</span></button></div>${image(photos.couple,'Friends walking together outdoors')}</div><div class="two-column top-space"><article class="page-card"><span class="eyebrow">WHAT YOU WILL DISCOVER</span><h2 style="font:38px var(--display)">Common ground.</h2><p>See which answers you share and which open a new conversation. You choose who receives the private invitation.</p></article><article class="page-card"><span class="eyebrow">BUILT FOR TRUST</span><h2 style="font:38px var(--display)">No verdicts.</h2><p>MIRRA does not claim to predict relationship success. It creates opportunities to understand each other more thoughtfully.</p></article></div>${state.user?`<div class="top-space">${button('View my invitations','invites','')}</div>`:''}</section>`}
async function fetchInvite(){try{const d=await request('/api/together/'+encodeURIComponent(state.inviteCode));state.invite=d.invite}catch(e){state.invite={error:e.message}}}
function invite(){const inv=state.invite;if(!inv)return `${intro('MIRRA TOGETHER','Opening your <em>invitation.</em>','')}`;if(inv.error)return `${intro('INVITATION','This link is not <em>available.</em>',escapeText(inv.error))}<section class="page-body container">${button('Back to MIRRA','home')}</section>`;if(inv.complete){const c=inv.comparison;return `${intro('TWO PERSPECTIVES','Where your worlds <em>meet.</em>',escapeText(inv.from)+' and '+escapeText(inv.guestName)+', here is a thoughtful starting point for conversation.')}<section class="page-body container"><div class="comparison-grid"><div><span class="eyebrow">SHARED CHOICES</span><strong>${c.sharedChoices} of ${c.total}</strong><p>This is a count of similar selections, not a compatibility rating.</p></div><div><span class="eyebrow">MOST CHOSEN APPROACHES</span><strong>${escapeText(c.first)}</strong><p>${escapeText(inv.from)} / ${escapeText(c.second)} for ${escapeText(inv.guestName)}</p></div></div><div class="top-space"><h2 style="font:45px var(--display)">Eight places to begin talking.</h2><div class="list-rows">${c.patterns.map(x=>`<div class="list-row"><span>${escapeText(x.question)}</span><small>${x.similar?'Similar responses':'Different perspectives'}</small></div>`).join('')}</div></div><p class="privacy-note">${c.note}</p>${button('Explore MIRRA','discover')}</section>`}
return `${intro('A PRIVATE INVITATION',escapeText(inv.from)+' invited you<br>to <em>reflect together.</em>','Eight small questions. No wrong answers. Your shared response is visible to anyone who has this invitation link.')}<section class="page-body container"><div class="form-card"><h2>Join the conversation.</h2><form id="guest-name-form"><label class="field"><span>YOUR FIRST NAME</span><input name="name" id="guest-name" required minlength="2" maxlength="60" placeholder="How should we call you?"></label><button class="btn dark" type="submit">Begin reflection <span>↗</span></button></form></div></section>`}
function invites(){if(!state.user)return account();return `${intro('YOUR CONNECTIONS','Invitations &<br><em>shared reflections.</em>','You control who receives a link. A completed invitation can open an honest and useful conversation.')}<section class="page-body container">${state.shareUrl?`<div class="invite-box"><span class="eyebrow">YOUR INVITATION IS READY</span><h2 style="font:42px var(--display)">A conversation worth sharing.</h2><div class="invite-code">${escapeText(state.shareUrl)}</div><button class="btn dark" data-action="copy-invite">Copy invitation link <span>↗</span></button></div>`:''}<div class="dash-heading"><h2>My invitations.</h2><button class="btn small" data-action="start-together">Create another <span>↗</span></button></div><div class="list-rows">${state.invites.length?state.invites.map(v=>`<div class="list-row"><div><b>${v.complete?'Shared reflection complete':'Awaiting a response'}</b><div class="muted">${new Date(v.created_at).toLocaleDateString()} ${v.guest_name?' · '+escapeText(v.guest_name):''}</div></div><button class="btn small" data-invite-open="${escapeText(v.id)}">${v.complete?'View comparison':'Copy link'} ↗</button></div>`).join(''):'<div class="empty">Your shared experiences will appear here.</div>'}</div></section>`}
function journal(){const local=getLocal('journal',[]),entries=state.user?state.journal:local;const now=new Date(),prompt=prompts[Math.floor(now.getTime()/86400000)%prompts.length];const days=new Set(entries.map(x=>new Date(x.created_at||x.date).toDateString())).size;return `${intro('YOUR PRIVATE JOURNAL','Room to <em>reflect.</em>','A little space to find words for what matters. No performance, no perfect answers.')}<section class="page-body container"><div class="journal-layout"><div><div class="daily-card"><span class="eyebrow">TODAY’S QUESTION</span><h2>${prompt}</h2><p>Begin wherever you are. A sentence is enough.</p></div><form id="journal-form"><label class="field"><span>A THOUGHT OF YOUR OWN</span><textarea required minlength="2" maxlength="3000" name="text" placeholder="I noticed something about myself today…"></textarea></label><button class="btn dark" type="submit">Save my reflection <span>↗</span></button><p class="privacy-note">${state.user?'Saved privately to your account.':'Saved privately in this browser. Sign in to sync across devices.'}</p></form></div><aside><span class="eyebrow">THE COLLECTION</span><h2 style="font:55px/1 var(--display);margin:15px 0 26px">Your recent thoughts.</h2><p class="small-text">${entries.length} entries across ${days} days.</p><div class="list-rows">${entries.length?entries.map(x=>`<article class="journal-entry"><time>${new Date(x.created_at||x.date).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}</time><p>${escapeText(x.body||x.text)}</p></article>`).join(''):'<div class="empty">It begins with one honest sentence.</div>'}</div></aside></div></section>`}
function account(){const u=state.user;return `${intro('YOUR SPACE',u?'Welcome back,<br><em>'+escapeText(u.name)+'.</em>':'A personal space<br>that feels <em>your own.</em>',u?'Your reflections, reports and shared experiences in one thoughtful place.':'Create a private account to keep your reports, journal and invitations together across devices.')}<section class="page-body container">${u?`<div class="account-panel"><div class="page-card"><span class="eyebrow">MY MIRRA PROFILE</span><h2 style="font:45px var(--display)">${escapeText(u.name)}</h2><p class="small-text">${escapeText(u.email)}</p><div class="group-buttons">${button('My reports','account','')}${button('My invitations','invites','')}</div><div class="top-space"><button class="btn-link" data-action="export-data">Export my data ↓</button><p><button class="btn-link" data-action="logout">Sign out ↗</button></p><p><button class="btn-link sensitive" data-action="delete-account">Delete account and data</button></p></div></div><div class="page-card"><span class="eyebrow">COLLECTED REFLECTIONS</span><h2 style="font:45px var(--display)">Your journey so far.</h2><div class="list-rows">${state.reportHistory.length?state.reportHistory.map(x=>`<div class="list-row"><div><b>${escapeText(x.journey==='ipip50'?'The Personality Atlas':genres[x.journey]?.title||x.journey)}</b><div class="muted">${new Date(x.created_at).toLocaleDateString()}</div></div><small>Saved</small></div>`).join(''):'<div class="empty">Nothing saved yet. Your next discovery could begin today.</div>'}</div></div></div>${button('Discover an experience','discover')}`:`<div class="form-card"><span class="eyebrow">${state.signMode==='register'?'NEW TO MIRRA':'WELCOME BACK'}</span><h2>${state.signMode==='register'?'A space for you.':'Make yourself at home.'}</h2><p class="small-text">${state.config.accounts?'Private, secure account storage.':'Account registration is currently unavailable; you can explore assessments without signing in.'}</p><form id="auth-form">${state.signMode==='register'?`<label class="field"><span>YOUR NAME</span><input required name="name" autocomplete="name" minlength="2" placeholder="What should we call you?"></label>`:''}<label class="field"><span>EMAIL ADDRESS</span><input required name="email" type="email" autocomplete="email" placeholder="you@example.com"></label><label class="field"><span>PASSWORD</span><input required name="password" type="password" minlength="10" autocomplete="${state.signMode==='register'?'new-password':'current-password'}" placeholder="At least ten characters"></label>${state.signMode==='register'?`<label class="checkline"><input type="checkbox" name="adult" required> I confirm that I am 18 or older.</label>`:''}<button class="btn dark" type="submit" ${state.config.accounts?'':'disabled'}>${state.signMode==='register'?'Create my space':'Sign in'} <span>↗</span></button><p id="auth-error" class="error"></p></form><button class="btn-link" data-action="toggle-auth">${state.signMode==='register'?'Already have an account? Sign in.':'New here? Create an account.'}</button><p class="privacy-note">MIRRA does not sell your journal or assessment answers. You can export or delete account data whenever you choose. This early version uses email and password authentication; email recovery is not configured yet.</p></div>`}</section>`}
function mirror(){return `${intro('THE PERSONAL MIRROR','A conversation<br>with <em>yourself.</em>','Reflect on situations, decisions and relationships with an attentive guide. Your own words remain the starting point.')}<section class="page-body container"><div class="two-column"><div class="page-card"><span class="eyebrow">REFLECTION COMPANION</span><h2 style="font:53px var(--display);margin:15px 0">A question can change the way you see things.</h2><p class="lead">${state.config.ai?'An AI companion can draw on recent reports you have saved, but only after you give permission for this conversation.':'Guided reflection is available. AI-generated replies will become available when a model provider is connected.'}</p><p class="privacy-note">This tool is for personal reflection. It is not therapy, clinical advice or crisis support.</p></div><div><div class="conversation">${state.mirror.length?state.mirror.map(m=>`<div class="bubble ${m.who==='user'?'self':'agent'}">${escapeText(m.text)}</div>`).join(''):'<div class="bubble agent">Hello. What is something you have been noticing about yourself recently?</div>'}</div>${!state.user?`<div class="empty">${button('Sign in to use your personal mirror','account')}</div>`:`<form id="mirror-form"><label class="field"><span>WHAT IS ON YOUR MIND?</span><textarea name="message" required minlength="4" maxlength="1000" placeholder="I have been thinking about…" style="min-height:110px"></textarea></label><label class="checkline"><input type="checkbox" required name="consent"> I consent to my message and up to three recent saved reports being used to generate this reflection.</label><button class="btn dark" type="submit">Reflect on this <span>↗</span></button></form>`}</div></div></section>`}
function stories(){const story=storyCollection[state.story]||storyCollection[0];const chapter=story.chapters[state.chapter];return `${intro('INTERACTIVE STORIES','Every choice<br>tells a <em>story.</em>','Small fictional moments, inspired by the delicate art of being human. Your choices shape the conversation, not a diagnosis.')}<section class="page-body container"><div class="tab-row">${storyCollection.map((s,i)=>`<button class="${state.story===i?'on':''}" data-story="${i}">${escapeText(s.title)}</button>`).join('')}</div><div class="story-frame"><div class="story-visual">${image(story.image,'Editorial scene for '+story.title)}</div><div class="story-card"><span class="eyebrow">${story.tag} / CHAPTER ${state.chapter+1} OF ${story.chapters.length}</span><h2>${escapeText(story.title)}</h2><p>${escapeText(chapter.text)}</p>${chapter.choices.map((v,i)=>`<button class="story-choice" data-story-answer="${i}">${i+1}. ${escapeText(v)} <span style="float:right">↗</span></button>`).join('')}<p class="privacy-note">These stories are reflective fiction. There is no scientifically scored result.</p></div></div></section>`}
function membership(){const plans=[{id:'deepDive',name:'Deep Dive',price:'$4.99',time:'one time',copy:'A more detailed personal interpretation and printable report.',features:['Extended report','More reflective prompts','Beautiful print layout']},{id:'plus',name:'MIRRA Plus',price:'$7.99',time:'per month',copy:'A growing personal space with premium journeys and deeper reflection.',features:['All premium chapters','Personal Mirror','Saved history']},{id:'together',name:'Together Plus',price:'$12.99',time:'per month',copy:'Make shared exploration part of your relationship rituals.',features:['Shared reflection library','Conversation collections','Two person experiences']}];return `${intro('MIRRA MEMBERSHIP','More room<br>to <em>discover.</em>','Begin with a free experience. Go deeper only when it feels meaningful to you.')}<section class="page-body container"><div class="pricing-grid">${plans.map((p,i)=>`<article class="price-card ${i===1?'featured':''}"><span class="eyebrow">${p.name.toUpperCase()}</span><h3>${p.name}</h3><div class="price">${p.price}<span style="font:12px var(--sans);margin-left:9px">${p.time}</span></div><p>${p.copy}</p><p>${p.features.join(' · ')}</p><button class="btn ${i===1?'cream':''}" data-checkout="${p.id}" ${state.config.products[p.id]?'':'disabled'}>${state.config.products[p.id]?'Choose '+p.name:'Coming soon'} <span>↗</span></button></article>`).join('')}</div><p class="privacy-note">Membership prices are proposed launch prices. Checkout is available only where a verified payment link is configured. Free experiences remain free. Paid access is not yet automatically unlocked without confirmed Stripe webhook integration.</p></section>`}
function science(){return `${intro('THE SCIENCE & THE ART','Measure carefully.<br>Understand <em>generously.</em>','A responsible approach to personality respects evidence, uncertainty and the fact that people can change.')}<section class="page-body container"><div class="two-column"><article class="page-card"><span class="eyebrow">THE FOUNDATION</span><h2 style="font:50px var(--display)">The Big Five.</h2><p>The 50-item assessment uses the public-domain IPIP Big Five markers. Five dimensions are scored using the published reverse-key scheme, with 10 items per dimension. Our transformed 0 to 100 index is not a population percentile.</p><a class="btn" href="https://ipip.ori.org/new_ipip-50-item-scale.htm" target="_blank" rel="noreferrer">Read the original instrument ↗</a></article><article class="page-card"><span class="eyebrow">THE CREATIVE CHAPTERS</span><h2 style="font:50px var(--display)">Questions worth asking.</h2><p>Original relationship, values and lifestyle journeys are for structured self reflection. Their styles are descriptive prompts, not validated psychometric categories, diagnoses or compatibility predictions.</p>${button('Try a reflection','discover')}</article></div><div class="page-card top-space"><span class="eyebrow">YOUR PRIVACY</span><h2 style="font:43px var(--display)">Your words belong to you.</h2><p>Signed-in accounts store reports, invitations and journal entries in MIRRA's application database. Guest reports and journal entries stay in browser storage. Shared links allow anyone with the link to see the resulting comparison after both participants respond. You can export or delete your account data at any time.</p></div></section>`}
async function loadReports(){if(!state.user)return;try{state.reportHistory=(await request('/api/reports')).reports||[]}catch(e){console.warn(e)}}
async function loadInvites(){if(!state.user)return;try{state.invites=(await request('/api/invites')).invites||[]}catch(e){console.warn(e)}}
async function loadJournal(){if(!state.user)return;try{state.journal=(await request('/api/journal')).entries||[]}catch(e){console.warn(e)}}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{const box=document.createElement('textarea');box.value=text;document.body.append(box);box.select();document.execCommand('copy');box.remove();toast('Copied to clipboard.')}}
function shareCard(){const r=state.result||getLocal('recentReport',null);if(!r)return;const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const ctx=canvas.getContext('2d');ctx.fillStyle='#f6f3ed';ctx.fillRect(0,0,1080,1350);ctx.fillStyle='#243e31';ctx.fillRect(50,50,980,1250);ctx.fillStyle='#e7e3dc';ctx.font='30px Georgia';ctx.fillText('M I R R A',110,155);ctx.fillStyle='#d5a788';ctx.font='18px Arial';ctx.fillText('A PERSONAL REFLECTION',110,240);ctx.fillStyle='#f7f3eb';ctx.font='78px Georgia';ctx.fillText('A portrait of you.',110,340);if(r.journey==='ipip50'){let y=480;for(const item of r.score.dimensions){ctx.font='25px Arial';ctx.fillText(item.name,110,y);ctx.fillStyle='#536e5e';ctx.fillRect(110,y+23,750,12);ctx.fillStyle='#e0c4aa';ctx.fillRect(110,y+23,750*item.index/100,12);ctx.fillStyle='#f7f3eb';ctx.font='32px Georgia';ctx.fillText(String(item.index),880,y+2);y+=132}}else{ctx.font='50px Georgia';ctx.fillText(String(r.score.name||r.score.label).slice(0,30),110,520)}ctx.font='23px Arial';ctx.fillStyle='#b9c6ba';ctx.fillText('Personal reflection, not a diagnosis.',110,1170);ctx.fillText('mirra / the psychology of being human',110,1235);const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='mirra-personality-portrait.png';a.click();toast('Your portrait is ready.')}
function navigateActions(el){if(el.dataset.route){const r=el.dataset.route;route(r);if(r==='account')loadReports().then(render);if(r==='journal')loadJournal().then(render);if(r==='invites')loadInvites().then(render);return true}if(el.dataset.open){startQuiz(el.dataset.open);return true}if(el.dataset.answer){state.answers[state.idx]=Number(el.dataset.answer);render();return true}if(el.dataset.story!==undefined){state.story=Number(el.dataset.story);state.chapter=0;state.choices=[];render();return true}if(el.dataset.storyAnswer!==undefined){state.choices.push(Number(el.dataset.storyAnswer));state.chapter++;if(state.chapter>=storyCollection[state.story].chapters.length){state.chapter=0;toast('A thoughtful ending. Every choice opened a different conversation.')}render();return true}if(el.dataset.inviteOpen){state.inviteCode=el.dataset.inviteOpen;fetchInvite().then(()=>{if(state.invite?.complete)route('invite');else copy(location.origin+'/?invite='+state.inviteCode)});return true}if(el.dataset.checkout){const link=state.config.products[el.dataset.checkout];if(!link)return toast('Checkout is not configured yet.');if(!state.user){state.signMode='register';route('account');return toast('Create a private account before purchasing.')}const u=new URL(link);u.searchParams.set('client_reference_id',state.user.id);location.href=u.toString();return true}return false}
async function action(name){if(name==='previous'){if(state.idx>0){state.idx--;render()}else route('discover')}else if(name==='next'){if(!state.answers[state.idx])return;const len=state.journey==='together'?8:state.journey==='ipip50'?state.ipip.length:genres[state.journey].questions.length;if(state.idx+1<len){state.idx++;render()}else await completeQuiz()}else if(name==='toggle-auth'){state.signMode=state.signMode==='register'?'login':'register';render()}else if(name==='start-together'){state.journey='together';state.answers=state.pendingTogether||[];state.idx=0;state.pendingTogether=null;route('quiz')}else if(name==='copy-invite'){copy(state.shareUrl)}else if(name==='share-result'){const r=state.result;const s=r.journey==='ipip50'?'My MIRRA Big Five reflection: '+r.score.dimensions.map(x=>x.name+' '+x.index+'/100').join(', '):'My MIRRA reflection: '+(r.score.name||r.score.label)+'. '+r.score.description;copy(s+' · Self reflection only, not a diagnosis.')}else if(name==='download-card')shareCard();else if(name==='logout'){await request('/api/logout',{method:'POST',json:{}}).catch(()=>{});state.user=null;state.entitlements=[];state.reportHistory=[];route('home');toast('You have signed out.')}else if(name==='export-data'){try{const data=await request('/api/export');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='mirra-my-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Data export downloaded.')}catch(e){toast(e.message)}}else if(name==='delete-account'){if(!confirm('Permanently delete your MIRRA account, reports, journal and invitations? This cannot be undone.'))return;try{await request('/api/account',{method:'DELETE',json:{}});state.user=null;route('home');toast('Your account was deleted.')}catch(e){toast(e.message)}}}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-route],[data-open],[data-answer],[data-action],[data-story],[data-story-answer],[data-invite-open],[data-checkout]');if(!nav)return;e.preventDefault();if(navigateActions(nav))return;try{await action(nav.dataset.action)}catch(e){toast(e.message)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['auth-form','journal-form','guest-name-form','guest-answer-form','mirror-form'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));try{if(form.id==='auth-form'){const d=await request(state.signMode==='register'?'/api/register':'/api/login',{method:'POST',json:state.signMode==='register'?{...data,adult:form.querySelector('[name=adult]')?.checked}:data});state.user=d.user;await Promise.all([loadReports(),loadJournal(),loadInvites()]);if(state.pendingTogether){state.journey='together';state.answers=state.pendingTogether;state.idx=7;state.pendingTogether=null;await completeQuiz()}else{route('account');toast('Welcome to your space.')}}else if(form.id==='journal-form'){const text=data.text.trim();if(state.user){await request('/api/journal',{method:'POST',json:{text}});await loadJournal()}else{const local=getLocal('journal',[]);local.unshift({text,date:new Date().toISOString()});putLocal('journal',local)}render();toast('Reflection saved privately.')}else if(form.id==='guest-name-form'){state.guestName=data.name;state.journey='together';state.answers=[];state.idx=0;state.guestMode=true;route('quiz')}else if(form.id==='mirror-form'){state.mirror.push({who:'user',text:data.message});render();const d=await request('/api/mirror',{method:'POST',json:{message:data.message}});state.mirror.push({who:'agent',text:d.answer});render()} }catch(err){const target=$('#auth-error');if(target)target.textContent=err.message;else toast(err.message)}});
// Guest Together submission is intentionally separate from signed-in invitation creation.
const originalComplete=completeQuiz;
completeQuiz=async function(){if(state.guestMode&&state.journey==='together'){try{await request('/api/together/'+state.inviteCode+'/answer',{method:'POST',json:{name:state.guestName,answers:state.answers}});state.guestMode=false;await fetchInvite();route('invite')}catch(e){toast(e.message)}return}return originalComplete()};
$('#menu-toggle').addEventListener('click',()=>{const nav=$('#mobile-nav');nav.hidden=!nav.hidden;$('#menu-toggle').setAttribute('aria-expanded',String(!nav.hidden))});
window.addEventListener('keydown',e=>{if(state.route!=='quiz'||/input|textarea/i.test(document.activeElement?.tagName||''))return;const max=state.journey==='ipip50'?5:4;if(/^[1-5]$/.test(e.key)&&Number(e.key)<=max){state.answers[state.idx]=Number(e.key);render()}else if(e.key==='Enter'&&state.answers[state.idx])action('next')});
boot();
